SELECT DISTINCT agency_name, agency_state_name, ori FROM crime.cde_reta WHERE year=2025 AND (
  agency_name ILIKE '%New York%Police%' OR agency_name ILIKE '%Los Angeles Police%' OR agency_name ILIKE '%Chicago Police%' OR agency_name ILIKE '%Houston Police%' OR agency_name ILIKE '%Phoenix Police%' OR agency_name ILIKE '%Philadelphia Police%' OR agency_name ILIKE '%San Antonio Police%' OR agency_name ILIKE '%San Diego Police%' OR agency_name ILIKE '%Dallas Police%' OR agency_name ILIKE '%Austin Police%' OR agency_name ILIKE '%Jacksonville%Sheriff%' OR agency_name ILIKE '%San Jose Police%' OR agency_name ILIKE '%Fort Worth Police%' OR agency_name ILIKE '%Columbus Division of Police%' OR agency_name ILIKE '%Charlotte-Mecklenburg%' OR agency_name ILIKE '%San Francisco Police%' OR agency_name ILIKE '%Indianapolis Metropolitan%' OR agency_name ILIKE '%Seattle Police%' OR agency_name ILIKE '%Denver Police%' OR agency_name ILIKE '%Metropolitan Police Dept%' OR agency_name ILIKE '%Nashville%Metro%' OR agency_name ILIKE '%Oklahoma City Police%' OR agency_name ILIKE '%Boston Police%' OR agency_name ILIKE '%El Paso Police%' OR agency_name ILIKE '%Portland Police%' OR agency_name ILIKE '%Las Vegas Metro%' OR agency_name ILIKE '%Memphis Police%' OR agency_name ILIKE '%Louisville Metro%' OR agency_name ILIKE '%Baltimore Police%' OR agency_name ILIKE '%Milwaukee Police%'
)
